import java.util.Scanner;

public class Main10 {
    public static void main(String[] args) {
        Scanner scn = new Scanner(System.in);
        int numberInput = scn.nextInt();
        String inputString = scn.next();
        String workingString = inputString;
        String bracketsHolder = "_";
        int startIdx = -1;
        int totalLenStr = workingString.length();

        for (int index = 0; index < totalLenStr; index++) {
            char currentChar = workingString.charAt(index);
            if (currentChar == '(') {
                startIdx = index;
            } else if (currentChar == ')') {
                bracketsHolder += workingString.substring(startIdx + 1, index) + "_";
                workingString = workingString.substring(0, startIdx) + "_" + workingString.substring(index + 1);
                totalLenStr = workingString.length();
                index = startIdx - 1;
                startIdx = -1;
            }
        }
        String[] bracketPartsArr = bracketsHolder.split("_");
        int bracketCountTotal = 0;
        for (String part : bracketPartsArr) {
            if (!part.equals("")) {
                bracketCountTotal++;
            }
        }
        String[] segmentsArr = workingString.split("_");
        int maxSegmentLen = 0;
        for (String segment : segmentsArr) {
            if (segment.length() > maxSegmentLen) {
                maxSegmentLen = segment.length();
            }
        }
        System.out.println(maxSegmentLen + " " + bracketCountTotal);
    }
}
